import{z as A,x as B,o as e,c as d,q as i,j as t,D as n,d as o,s as l,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"通胀预期锚定","description":"","frontmatter":{"title":"通胀预期锚定","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/inflation-anchoring.md","filePath":"econ/inflation-anchoring.md","lastUpdated":1791413859000}'),p={name:"econ/inflation-anchoring.md"};function m(C,a,h,D,c,S){const r=B("Mermaid");return e(),d("div",null,[a[2]||(a[2]=i('<h1 id="通胀预期锚定" tabindex="-1">通胀预期锚定 <a class="header-anchor" href="#通胀预期锚定" aria-label="Permalink to &quot;通胀预期锚定&quot;">​</a></h1><div class="epigraph"><p>长期预期若钉在目标上，短期冲击少进入工资与价格；一旦解钉，学习与指数化把通胀变成更持久的状态。</p><footer>—— Bernanke 对锚定的政策表述；Gürkaynak, Sack and Swanson 对远期通胀补偿；Coibion, Gorodnichenko and Kamdar 综述</footer></div><p><a href="/econ/expectations-management">上一课</a>给出沟通工具。本课缺口是<strong>长期通胀预期</strong>这个具体状态：锚定意味着什么、用什么测、解钉如何进入 NK。不重写 Odyssean 定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SW 类 NK 常把通胀目标写成常数，长期预期机械锚定。数据：十年通胀补偿与调查长期预期在目标制下较稳，但仍随原油、财政、体制新闻动（Gürkaynak 等）。解钉：学习把趋势通胀当时变系数；指数化与过去通胀进工资，使菲利普斯更陡或更持久。缺口是把「锚定」写成可破的信念，而不是永远的常数 \\(\\bar\\pi\\)。</p><p><span class="marginnote">术语翻译：「锚定」不是「预期正好等于 2%」这个数字，而是这个数字对短期冲击不敏感——油价涨、赤字大，大家仍相信长期通胀会被拉回目标。锚定程度 = 长期预期对冲击的载荷有多小。</span><span class="marginnote">Gürkaynak, Sack and Swanson 对远期通胀。Coibion, Gorodnichenko and Kamdar, <em>JEL</em> 2018。Orphanides and Williams 的学习与锚定。Hazell, Herreno, Nakamura and Steinsson 的区域菲利普斯。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>测量：调查长期预期、通胀掉期与 TIPS 远期（含风险溢价与流动性，要拆）。模型：趋势通胀 \\(\\pi_t^*\\) 为随机游走或学习过程；锚定 = \\(\\pi_t^*\\) 方差小且对短期冲击载荷小。政策：平均通胀目标、对称损失、财政货币合作（后课主导）影响 \\(\\pi^*\\)。HANK：家庭 CPI 预期解钉会立刻经高 MPC 与工资要求进入需求，比专家锚定更要紧。</p>',8)),(e(),t(s,null,{default:n(()=>[l(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TGT%5B%22%E5%90%8D%E4%B9%89%E9%94%9A%20%2F%20%E7%9B%AE%E6%A0%87%22%5D%20--%3E%20STAR%5B%22%E8%B6%8B%E5%8A%BF%E9%80%9A%E8%83%80%20%CF%80*%22%5D%0A%20%20SHOCK%5B%22%E7%9F%AD%E6%9C%9F%E5%86%B2%E5%87%BB%22%5D%20--%3E%20PI%5B%22%E7%9F%AD%E6%9C%9F%20%CF%80%22%5D%0A%20%20STAR%20--%3E%20PI%0A%20%20LEARN%5B%22%E5%AD%A6%E4%B9%A0%20%2F%20%E6%8C%87%E6%95%B0%E5%8C%96%22%5D%20--%3E%20STAR%0A%20%20UN%5B%22%E8%A7%A3%E9%92%89%22%5D%20--%3E%20PERS%5B%22%E6%9B%B4%E6%8C%81%E4%B9%85%E7%9A%84%E9%80%9A%E8%83%80%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与疏忽：低通胀年代容量不分配给 CPI，看起来像锚定，其实是不注意；一旦通胀升高，更新跳升，像突然解钉。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[o("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是长期信念进入当期定价（前瞻菲利普斯含 \\(\\mathbb{E}\\pi_{t+1}\\)，迭代后含长期）。锚定把冲击的折现核压住；解钉等于把单位根或近单位根放进通胀。财政：若人相信债务最终靠铸币税，锚定失败——Leeper 财政理论接口留给主导课。沟通：重复目标只能在 Odyssean 可信或 Delphic 不破坏信任时钉住。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"1970 年代是解钉的经典样本；1990 年代后目标制是锚定样本。样本分裂使 SW 全样本估计的持续性是混合物。")],-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：锚像船锚——风浪（短期冲击）只让船（当期通胀）绕着锚打转；锚绳一断，船随波逐流，而且按 1970 年代的经验，重新抛锚可能要花十年和一次深度衰退的代价。")],-1)),(e(),t(s,null,{default:n(()=>[l(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E4%B8%80%E6%AC%A1%E6%88%90%E6%9C%AC%E5%86%B2%E5%87%BB%22%5D%20--%3E%20BR%7B%22%E9%95%BF%E6%9C%9F%E9%A2%84%E6%9C%9F%E9%94%9A%E4%BD%8F%E4%BA%86%E5%90%97%3F%22%7D%0A%20%20BR%20--%20%22%E9%94%9A%E5%AE%9A%22%20--%3E%20TEMP%5B%22%E9%80%9A%E8%83%80%E6%9A%82%E6%97%B6%E4%B8%8A%E5%8D%87%E5%90%8E%E5%9B%9E%E8%90%BD%22%5D%0A%20%20BR%20--%20%22%E8%A7%A3%E9%92%89%22%20--%3E%20UP%5B%22%E9%95%BF%E6%9C%9F%E9%A2%84%E6%9C%9F%E4%B8%8A%E7%A7%BB%22%5D%0A%20%20UP%20--%3E%20WAGE%5B%22%E5%B7%A5%E8%B5%84%E4%B8%8E%E5%AE%9A%E4%BB%B7%E8%A6%81%E6%B1%82%E6%8F%90%E9%AB%98%22%5D%0A%20%20WAGE%20--%3E%20COST%5B%22%E6%88%90%E6%9C%AC%E4%B8%8E%E4%BB%B7%E6%A0%BC%E7%9C%9F%E7%9A%84%E4%B8%8A%E6%B6%A8%22%5D%0A%20%20COST%20--%3E%20CONF%5B%22%E9%A2%84%E6%9C%9F%E8%A2%AB%E7%8E%B0%E5%AE%9E%E5%86%8D%E7%A1%AE%E8%AE%A4%22%5D%0A%20%20CONF%20--%3E%20UP%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不预测下一次解钉。不把能源权重的 CPI 会计当预期理论。工资–价格螺旋的全部制度史放不下。下一课把有限理性收成 NK 的显式偏离 RE，作为本单元收束。</p><p>后课默认：锚定 = 趋势通胀信念的稳定；测量要分调查与市场、分家庭与专家。下一课：有限理性 NK 的系统写法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>锚定是长期通胀信念对短期冲击的低载荷。</li><li>学习、指数化、疏忽的注意力跳升都可以表现为解钉。</li><li>家庭预期对 HANK 传导更关键。</li><li>出处：Gürkaynak–Sack–Swanson。</li></ul>',5))])}const k=A(p,[["render",m]]);export{u as __pageData,k as default};
